import React, { useMemo, useState } from "react";
import { useForm, SubmitHandler } from "react-hook-form";
import { yupResolver } from "@hookform/resolvers/yup";
import * as yup from "yup";
import { useTranslation } from "gatsby-plugin-react-i18next";
import { db } from "../../firebaseConfig";
import { collection, addDoc, Timestamp } from "firebase/firestore";
import emailjs from "@emailjs/browser";
import { buildEmailMessage, getEmailJsConfig } from "../../utils/emailjs";
import { trackLeadCapture } from "../utils/analytics";
import type { JourneyCtaType } from "../utils/cta";

type FormData = {
  fullName: string;
  company: string;
  city: string;
  websiteUrl: string;
  email: string;
  message: string;
};

type ContactFormProps = {
  leadIntent?: JourneyCtaType;
  intro?: string;
  submitLabel?: string;
};

export default function ContactForm({
  leadIntent,
  intro,
  submitLabel,
}: ContactFormProps) {
  const [sending, setSending] = useState(false);
  const [submitted, setSubmitted] = useState(false);
  const [submitError, setSubmitError] = useState("");
  const { t } = useTranslation();
  const leadIntentLabel = leadIntent
    ? (t(`journeyCtas.types.${leadIntent}.label`) as string)
    : "";
  const schema = useMemo(
    () =>
      yup.object({
        fullName: yup
          .string()
          .trim()
          .required(t("contact.form.validation.requiredName") as string),
        company: yup
          .string()
          .trim()
          .required(t("contact.form.validation.requiredCompany") as string),
        city: yup
          .string()
          .trim()
          .required(t("contact.form.validation.requiredCity") as string),
        websiteUrl: yup
          .string()
          .trim()
          .required(t("contact.form.validation.requiredWebsite") as string)
          .url(t("contact.form.validation.invalidWebsite") as string),
        email: yup
          .string()
          .trim()
          .email(t("contact.form.validation.invalidEmail") as string)
          .required(t("contact.form.validation.requiredEmail") as string),
        message: yup
          .string()
          .trim()
          .required(t("contact.form.validation.requiredMessage") as string)
          .min(20, t("contact.form.validation.minMessage") as string),
      }) as yup.ObjectSchema<FormData>,
    [t]
  );

  const {
    register,
    handleSubmit,
    reset,
    formState: { errors },
  } = useForm<FormData>({
    resolver: yupResolver(schema),
    mode: "onChange",
    defaultValues: {
      fullName: "",
      company: "",
      city: "",
      websiteUrl: "",
      email: "",
      message: "",
    },
  });

  const onSubmit: SubmitHandler<FormData> = async (data) => {
    setSending(true);
    setSubmitError("");
    try {
      await addDoc(collection(db, "contactMessages"), {
        ...data,
        ...(leadIntent ? { leadIntent } : {}),
        createdAt: Timestamp.now(),
      });

      const emailConfig = getEmailJsConfig();

      if (emailConfig) {
        const emailMessage = buildEmailMessage("contact", {
          fullName: data.fullName,
          company: data.company,
          city: data.city,
          websiteUrl: data.websiteUrl,
          email: data.email,
          leadIntent: leadIntentLabel || undefined,
          message: data.message,
        });

        try {
          await emailjs.send(
            emailConfig.serviceId,
            emailConfig.templateId,
            emailMessage,
            emailConfig.publicKey
          );
        } catch (error) {
          console.error("Error sending contact email:", error);
        }
      } else {
        console.error("Missing EmailJS environment variables");
      }

      try {
        await trackLeadCapture({
          form_name: "contact_form",
          lead_type: leadIntent || "contact_request",
          method: "form_submit",
        });
      } catch (error) {
        console.error("Error tracking contact lead capture:", error);
      }

      reset();
      setSubmitted(true);
    } catch (error) {
      console.error("Error saving contact request:", error);
      setSubmitError(
        (t("contact.form.submitError") as string) ||
          "We could not send your request right now. Please try again."
      );
    } finally {
      setSending(false);
    }
  };

  return (
    <form onSubmit={handleSubmit(onSubmit)} className="w-full sm:w-[400px]">
      {submitted ? (
        <div className="flex flex-col items-center mt-8 rounded-2xl border border-purplesemilight/40 bg-primary/70 p-6 text-center shadow-sm supports-[backdrop-filter]:bg-purplesemilight/20 supports-[backdrop-filter]:backdrop-blur">
          <p className="text-light text-base sm:text-lg font-semibold mb-2">
            {t("contact.form.thankYou") || "Thank you for your message!"}
          </p>
          <p className="text-light/70 text-sm sm:text-base mb-4">
            {leadIntentLabel
              ? (t("contact.form.confirmationWithIntent", {
                  intent: leadIntentLabel,
                }) as string)
              : (t("contact.form.confirmation") as string) ||
                "We will get back to you shortly."}
          </p>
          <button
            onClick={() => {
              reset();
              setSubmitted(false);
            }}
            type="button"
            className="w-full rounded-full bg-purplesemilight px-5 py-2.5 text-dark font-semibold text-sm sm:text-base text-center transition duration-[400ms] hover:opacity-90"
          >
            {t("contact.form.backToForm") || "Back to Form"}
          </button>
        </div>
      ) : (
        <>
          <div className="text-sm sm:text-base text-light/70 mb-6">
            {intro || t("contact.subtitle")}
          </div>

          {leadIntentLabel ? (
            <div className="mb-6 rounded-2xl border border-white/15 bg-white/5 px-4 py-3 text-sm text-light/80">
              <span className="font-semibold text-light/90">
                {t("contact.form.intentLabel")}{" "}
              </span>
              {leadIntentLabel}
            </div>
          ) : null}

          <div className="mb-6 rounded-2xl border border-white/15 bg-white/5 px-4 py-3 text-sm text-light/75">
            {t("contact.form.helper")}
          </div>

          {/* Name */}
          <label className={styles.label} htmlFor="contact-name">
            {t("contact.form.name") || "Name"}
          </label>
          <input
            id="contact-name"
            type="text"
            autoComplete="name"
            className={styles.input}
            aria-invalid={!!errors.fullName}
            {...register("fullName")}
          />
          {errors.fullName?.message ? (
            <p className={styles.error}>{errors.fullName.message}</p>
          ) : null}

          {/* Company */}
          <label className={`${styles.label} mt-4`} htmlFor="contact-company">
            {t("contact.form.company") || "Company"}
          </label>
          <input
            id="contact-company"
            type="text"
            autoComplete="organization"
            className={styles.input}
            aria-invalid={!!errors.company}
            {...register("company")}
          />
          {errors.company?.message ? (
            <p className={styles.error}>{errors.company.message}</p>
          ) : null}

          {/* City */}
          <label className={`${styles.label} mt-4`} htmlFor="contact-city">
            {t("contact.form.city") || "City"}
          </label>
          <input
            id="contact-city"
            type="text"
            autoComplete="address-level2"
            className={styles.input}
            aria-invalid={!!errors.city}
            {...register("city")}
          />
          {errors.city?.message ? (
            <p className={styles.error}>{errors.city.message}</p>
          ) : null}

          {/* Website URL */}
          <label className={`${styles.label} mt-4`} htmlFor="contact-website">
            {t("contact.form.website") || "Website URL"}
          </label>
          <input
            id="contact-website"
            type="url"
            autoComplete="url"
            className={styles.input}
            aria-invalid={!!errors.websiteUrl}
            {...register("websiteUrl")}
          />
          {errors.websiteUrl?.message ? (
            <p className={styles.error}>{errors.websiteUrl.message}</p>
          ) : null}

          {/* Email */}
          <label className={`${styles.label} mt-4`} htmlFor="contact-email">
            {t("contact.form.email") || "Email"}
          </label>
          <input
            id="contact-email"
            type="email"
            autoComplete="email"
            className={styles.input}
            aria-invalid={!!errors.email}
            {...register("email")}
          />
          {errors.email?.message ? (
            <p className={styles.error}>{errors.email.message}</p>
          ) : null}

          {/* Message */}
          <label className={`${styles.label} mt-4`} htmlFor="contact-message">
            {t("contact.form.message") || "Project details"}
          </label>
          <textarea
            id="contact-message"
            autoComplete="off"
            className={`${styles.input} ${styles.textarea}`}
            aria-invalid={!!errors.message}
            {...register("message")}
          />
          {errors.message?.message ? (
            <p className={styles.error}>{errors.message.message}</p>
          ) : null}

          {submitError ? (
            <p className="mt-4 rounded-xl border border-purplelight/40 bg-primary/70 px-4 py-3 text-sm text-light/85">
              {submitError}
            </p>
          ) : null}

          <div className="mt-6">
            <button
              type="submit"
              disabled={sending}
              className={`${styles.submit} ${sending ? "opacity-60 cursor-not-allowed" : ""}`}
            >
              {sending
                ? t("contact.form.sending") || "Sending..."
                : submitLabel || t("contact.form.submit") || "Send"}
            </button>
          </div>
        </>
      )}
    </form>
  );
}

const styles = {
  label: "block text-sm text-light/80",
  input:
    "mt-2 w-full rounded-xl border border-purplesemilight/50 bg-primary/70 px-4 py-3 text-sm sm:text-base text-light placeholder:text-purplelight/60 focus:outline-none focus:border-secondary focus:ring-2 focus:ring-secondary/40 transition",
  textarea: "min-h-[120px] resize-y",
  error: "mt-2 text-xs text-purplelight",
  submit:
    "w-full rounded-full bg-secondary px-6 py-3 text-light text-sm sm:text-base text-center transition duration-[400ms] hover:opacity-90",
};
