type EmailJsConfig = {
  serviceId: string;
  templateId: string;
  publicKey: string;
};

type FormMessagePayload = {
  formType: string;
  subject: string;
  body: string;
  fullName?: string;
  company?: string;
  city?: string;
  websiteUrl?: string;
  website?: string;
  email?: string;
  leadIntent?: string;
  message?: string;
  from_name?: string;
  reply_to?: string;
  [key: string]: string | undefined;
};

export const getEmailJsConfig = (): EmailJsConfig | null => {
  const serviceId = process.env.GATSBY_EMAILJS_SERVICE_ID;
  const templateId = process.env.GATSBY_EMAILJS_TEMPLATE_ID;
  const publicKey = process.env.GATSBY_EMAILJS_PUBLIC_KEY;

  if (!serviceId || !templateId || !publicKey) {
    return null;
  }

  return { serviceId, templateId, publicKey };
};

const formatLabel = (label: string, value?: string) => {
  if (!value) return "";
  return `${label}: ${value}`;
};

export const buildEmailMessage = (
  formType: "contact" | "partners" | "subscribe",
  fields: Record<string, string | undefined>
): FormMessagePayload => {
  const subjectMap = {
    contact: "Contact Form",
    partners: "Partners Form",
    subscribe: "Subscribe Form",
  } as const;

  const lines: string[] = [];

  if (formType === "contact") {
    lines.push(
      formatLabel("Name", fields.fullName),
      formatLabel("Company", fields.company),
      formatLabel("City", fields.city),
      formatLabel("Website URL", fields.websiteUrl),
      formatLabel("Email", fields.email),
      formatLabel("Request type", fields.leadIntent),
      formatLabel("Message", fields.message)
    );
  }

  // if (formType === "partners") {
  //   lines.push(
  //     formatLabel("Category", fields.category),
  //     formatLabel("Name", fields.name),
  //     formatLabel("Address", fields.address),
  //     formatLabel("Email", fields.email),
  //     formatLabel("Telephone", fields.telephone),
  //     formatLabel("Product Interest", fields.productInterest)
  //   );
  // }

  // if (formType === "subscribe") {
  //   lines.push(formatLabel("Email", fields.email));
  // }

  const body = lines.filter(Boolean).join("\n");

  return {
    formType,
    subject: subjectMap[formType],
    body,
    fullName: fields.fullName,
    company: fields.company,
    city: fields.city,
    websiteUrl: fields.websiteUrl,
    website: fields.websiteUrl,
    email: fields.email,
    leadIntent: fields.leadIntent,
    message: fields.message,
    from_name: fields.fullName,
    reply_to: fields.email,
    // category: fields.category,
    // name: fields.name,
    // address: fields.address,
    // telephone: fields.telephone,
    // productInterest: fields.productInterest,
  };
};
